	(1, 1687375800, '浩劫者12345', '欢迎来到圆焰站！这里是站长发的第一条留言

本站是模仿kami.im制作的，主要功能为留言板，但主题为圆焰，因为站长磕圆焰233，圆焰生一堆！(bushi

不幸的是kami.im在一个月前挂掉了，现在都没恢复，于是我萌生了一个自己建站的想法——

这个网站的代码完全是纯手搓的，前端完全自己写，后端用的.net core 6。上次写前端还是在初中 (现在刚高考完) ，刚好趁着这次机会写写后端。目前网站主要功能都以API的方式实现

目前为止，基本的留言系统已经可以运作。后面会陆续增加登录，设置头像，发送图片等功能

域名也暂时没注册，等拿到钱了就打算注册madohomu.love

本站还导入了kami.im的留言记录
kami.im崩溃之后，碧诗临时组建了Discord频道，里面刚好有人备份过kami.im的留言并整理发了出来，于是我就导入到了本站。非常感谢Yuudachi_Kai2备份的数据！

最后，祝各位圆焰厨能在本站留下美好的回忆！

站长QQ：3112611479
B站(包括其他平台)：浩劫者12345', NULL, NULL),
