aaa我要急死啦...！

总之还是希望各位马猴烧酒们有一个美好的结局吧（虽然不太可能啦）。

也祝我自己可以早日让ADHD好转，可以正常的生活吧。
已经不想再给他人添麻烦了。

2023.6.29  琉灵留', NULL, NULL),
