	(239, 1688027155, '焰圆永恒', '有时候真的很羡慕魔圆世界的魔法少女们，她们虽然要背负残酷的命运，但她们终究是得到了圆神的救赎，而我只能独自痛苦，身边没有人懂我(>﹏<)魔圆里我最喜欢小焰，大概是因为感觉自己和小焰挺像的吧，胆小内向，真正与二次元相遇后开始慢慢变得开朗起来，可残酷的现实总会给我带来难以愈合的伤；我也曾遇到过很像小圆的一束光，初二时我被全班孤立，她是我当时唯一的朋友，她的温柔鼓励和陪伴点亮了我那时的灰暗生活，没有她的我真的不知道怎么熬下去٩( ''ω'' )و 可我没能留得住那道光，不对，是我没有勇气留住她，初中毕业后就再也没有和她联系过，如今已经三年了...我真的好想联系她，好想和她继续做朋友！可我害怕她不记得我了，那我会直接崩溃的！就这样不打扰她也挺好的，她那么优秀，我那么普通，我和她注定不是一个圈子的人，我一直这样自我安慰着...可我还是很想她，真的好想好想，特别是每当自己遇到特别难受的时候，第一个想要寻求安慰的都是她她，会想要是有她在该多好，我都已经分不清我对她到底是只把她当朋友还是喜欢上她了Ծ‸Ծ焰圆一定要幸福永恒得在一起！算是弥补我和她的遗憾吧٩(๑`н´๑)۶', NULL, NULL),
	(240, 1688029167, '芙兰朵露轰炸联队', '走过了无数次轮回，你们的两人的情感每一次都变得更加强烈，深沉，想必我们常人也无法完全明白吧。
无论如何，你们都要好好幸福的在一起哦', NULL, NULL),
