	(348, 1688551844, '稚圭', '“小焰，你能回到过去，改变这种结局对吧...想求你一件事...你能帮帮那个，还没被丘比欺骗的我吗？”
“我...不想变成魔女，即使这世界上有很多不美好的事，但所有事情都有因果，只要相信...就一定会有好结果吧？”
“我要成为魔法少女！这世界上所有的魔女，未来的，过去的所以魔女，魔法少女的一切因果都由我来承担！”
“别伤心小焰，我们还会再见的，在那之前，只不过是短暂的分别...”
小焰对于小圆并不是只存有感激，同样也有爱，小焰希望小圆能以“鹿目圆”的身份好好的，用普通人的方式去生活，而并不是为了“魔女之夜”或者自己，去丢失性命。
丘比不明白人类的感情，小焰为了圆让丘比感受到了绝望。
“早く私と契約を結び、魔法少女になろう!”', NULL, NULL),
