	(354, 1688568882, '究极小圆前辈', '饱经风霜，我终于从桃色银河中找到了这里!我!馒头卡前辈!虽然平时不太正经!但是希望和小焰幸福度过余生的愿望才不会是虚假的!', NULL, NULL),
	(355, 1688569715, 'qb', '本人不是二次元，对于你们这种痴迷于虚拟角色的行为我很是不理解。我感觉应该分清现实和虚拟，她们好看归好看，但是终究不是真实存在的，我们要活在现实，每天去想一些实际的事，去充实自己的生活，而不是天天盯着纸片人。自己的幸福要自己去追求，绝对不能被虚拟的事物懵逼了双眼。我的生活很充实，下周日是小圆和小焰的婚礼，我要去捧个场🥳', NULL, NULL),
