	(442, 1689252547, '钟情下雨天', '圆神哪，现在总是找不到活着的意义，开始想每天虚无地渡过，连未来都看不清楚，找不到爱人在何处，身心上都有好多问题，每天总想哭一哭才能舒服，却有时候都哭不出来…之前还是有些想死的，但有一天突然变得好害怕，之后就不太想死了…圆神哪，这算罪吗，我的经历说出来也不值得同情，但我现在真的很难受…好想忘掉以前的事情，好想让她也忘掉好想让所有人都忘掉…时光能倒流的话就好了…每一天都好像在歇斯底里，不明白自己的精神状态…在不知道能不能说的地方说着不知道该不该说的话…在这里也是…圆神哪，你能原谅我吗…听着这里的音乐，又哭出来了…话说着说着就不知道怎么说了，这次就到这吧…我的圆神，再会了', NULL, NULL),
