	(457, 1689307004, '匿名用户', '魔法少女小圆——赞美光辉与后悔的荷马史诗
    这部动漫在我的印象中可比拟于蒙娜丽莎。确实因为这晦涩的剧情，还有这压抑到极致的画风。在描写这些魔法少女向着光辉的同时更多的是伴随着更多的绝望。沙耶香想让上条的手臂好起来。杏子想让父亲有更多的信徒。这种间接的无私的妄想却让他们走向绝望。在沙耶香看来，他对上条是独一无二的。认为他是不能够被麻美取代的天才。是一个曾经为他付出过的人。但这总自以为是的心理在后来也能看到。“现在的我杀死了魔女，是个除此之外没有任何意义的小棋子，让死去的身体动起来，假装还活着。”再不能接受自己无能为力的同时却又在埋怨这个世界。她傲慢的许下愿望却又自以为是的失望。一次次的打击的绝望让他存活下来只因为她别无选择。前期的傲慢和自己本身的无知让她把自己灵魂宝石扔下天台。但这一切，一切一切的本身却是为了让上条变得更好，或者说牺牲自我成全他人。但这却并不纯粹。掺杂了自己的主观意愿。认为只要上条手好了就会和自己在一起。认为自己是这个世界独一无二的天才。“我真是个笨蛋啊！”伴随着曾经所期望的样子，能一直看着上条演奏，甚至自己变成了演奏者。人鱼的演奏者。或许在沙耶香变成人鱼公主之前她一切的无知却显得不那么重要。奇迹本来是花费人命也买不到的东西。
    无独有偶，杏子是这个本来能避免死亡的角色却因为忍受不了这样的人生和沙耶香殉情了。“神啊，都已尽这样的人生了就让我再做一次幸福的梦吧！”杏子祈求的幸福并未到来，相反父亲却指定她为魔女，带着除了她的其他人全部上吊自杀了。而她这样的活着形如躯体。跟沙耶香是那么的像。或者说在她死的那一刻已经没有什么期望了。杏子从沙耶香身上看到了未来。看到了自己早晚变成的魔物。
    我并不想强调人的自私性。活着这样既出于他人却又完善于自我的愿望是最完美的。但却走向了这么华美的结局。她们本身并没有错。她们选择用希望去交换绝望。但到头来却不见希望的存在。不得不接受绝望的同时终将被其反噬。看吧，简单吧不能承受生命之轻。
    相较于动漫的结局我更在意的是红蓝殉情。现在看来这不仅仅是同命相连。而是不得不接受的命运。但晓美焰好像承受了这份绝望。在她的第一遍轮回的时候晓美焰自卑，深陷于痛苦的泥潭，等待他的只有悲惨的命运。她鹿目圆救了他。并没有看不起她，或者是圆的无私救了她。说实话，这种辞别为怀的结局让我看的很膈应。但我却能全盘接受叛逆的物语的结局。说回来，在晓美焰看来，鹿目圆就是他的一切。她不能忍受没有鹿目圆的世界。她不想让她成为圆环之理。他喜欢是真真切切的鹿目圆。但这却和圆的目标背道而驰。晓美圆一次次的失望让她意识到鹿目圆不会回爱的。终于她抓住了圆环之理。也抓住了鹿目圆。她要的不是圆环之理！是鹿目圆！她用自己承受着等同的绝望把一部分鹿目圆从圆环之理中拉了出来。成为了恶的一面。成为了这个世界完全对立的一面。而叛逆的物语中中后期也不难看出这种纠结于失与得的绝望。这样的世界，最终促使晓美焰成为了最特殊的一个魔女。她的性质是希望被自我处决。但触手却极力的摩擦着地面。散发出的怒吼。诉说着这世界的不公。这一切都是如此。
    最后总结一下，整部动漫没有什么恐怖的元素却被奉为恐怖的巅峰。她描写出人在面对极度痛苦的情况下自私的反应。为实现自己的梦想不惜牺牲自己和他人。而新房昭之却是把这一切具象话的写出来了而已。我知道整部番剧主旋律是圆的无私。但我却认为与其他人背道而行。从这些荒诞的人物背后。我又是谁，我终结会走向何种命运的结局。我终究是这个世界中最没用的棋子。这种负面情绪在我心中蔓延。生根发芽。或许是对于这个世界压抑的本质感到厌倦。但却无能为力。只能把这一切都怪罪于这个世界。现在这么想想，沙耶香这样梦幻般的结局也挺不错的。要么融为这世界的乌合之众。或者与这个世界同生同灭。黑白颠倒间。我仿佛看到了有人来接我。但却是晓美焰。他将要领我到何处？这个世界的中央？还是绝望的终点？所以说比希望更炙热，比绝望更深邃。', NULL, NULL),
	(458, 1689307690, '圆焰贴贴', '圆焰贴贴

最喜欢你们了
你们一定要幸福哦
', NULL, NULL),
	(459, 1689326960, 'まどか', '因为同学的推荐，最近才开始看这部老番，它打破了我对魔法少女的认知，奇迹，魔法背后，都有重大代价，但尽管如此，大家依旧在为自己的希望战斗着。里面塑造的让我印象最深的就是圆焰了，让我半夜落下了泪滴，后来才明白op歌词的含义，无论何时，无论何地，希望你们能永远在一起!最后有我想对小圆说的话：ねえまどか、あなたは僕の希望だよね、いつまでも、どこまでも！', NULL, NULL),
