	(467, 1689357001, 'kolde', '圆神，今天是第118天，早上出门晚了，看样赶不上校车，于是就坐地铁去了学校，途中还买了个三明治当早餐，下课后跟舍友吃了个中餐自助，吃的好饱吔，之后就一直没出门了，明天舍友要出去钓鱼三天，祝他玩的好点吧，晚安！', NULL, NULL),
