	(477, 1689508512, 'sayaka的好友', '圆神加油嗷', NULL, NULL),
	(478, 1689508968, '牛牛桑cc', '喜欢你就像裤子里的尿
暖暖的只有自己能知道', NULL, NULL),
	(479, 1689509319, 'cc', '从小学开始看魔圆，一直到现在大学还是很喜欢很喜欢
宿命式的悲剧总是最牵动人心的
', NULL, NULL),
	(480, 1689513174, '圆满', '小圆小焰', NULL, NULL),
	(481, 1689516951, '环', '准备二刷了，希望能增进我对磨圆的理解吧', NULL, NULL),
	(482, 1689520018, '绫音依旧', '圆神晚安(˘ω˘)', NULL, NULL),
	(483, 1689539081, 'kolde', '圆神，今天是第120天，又是睡到下午才醒，昨天同学也没跟我说能不能去，所以就没去，下午走去三条那边看看能不能赶上是祇園祭，去逛了一圈就找到会场了，直接封了好几条街，看到了明天要巡展的山鉾，真的很大呢，上面还有人在奏乐，之后找到一个类似中国夜市的地方，有很多小吃摊排成一排，今天吃了不少当地特色美食，要破产咯，明天还有花车游行，准备早点去找个好位置，安！', NULL, NULL),
	(484, 1689567271, '白晓礼', '非常美好的一天，爱来着圆环之理', NULL, NULL),
	(485, 1689572705, '匿名用户', '今天也非常没有意外，新的世界没有错乱，小圆啊，就算只有一会儿也好，让我倚靠一下你吧', NULL, NULL),
	(486, 1689572768, '晓美焰', '小圆，我爱你', NULL, NULL),
	(487, 1689589683, '今日为爱劫久', '有圆焰的世界太美好了！', NULL, NULL),
	(488, 1689592000, 'SobP', '祈求繁星 终会向着上游，
重组整个宇宙。

听EASON的告别娑婆时觉得和焰还算搭
', NULL, NULL),
	(489, 1689597820, '怠惰の木瓜', '真的很喜欢小圆，千言万语不知道说些什么，希望小圆和吼姆拉酱一起快乐的生活吧！还有希望魔圆正传第三季快点出！！！', NULL, NULL),
	(490, 1689603326, 'kianabocchi', '是新人！最近开始喜欢上魔圆的，圆酱和焰酱之间的感情实在是太爱了www准备立马二刷一遍。本人是初三生嘛，以前只看过巴啦啦小魔仙_(•̀ω•́ 」∠)_，从小就对魔法有着很大的想象，魔圆更是刷新了我整个人的认知，我从魔法中品到了更多更多的感情，是我以前不曾想过的！今后会一直喜欢下去的！~o(〃''▽''〃)o
祝魔圆的大家晚安，早安，午安啦！so so，还有在看这条的你！', NULL, NULL),
	(491, 1689606516, '绫音依旧', '圆神晚安(˘ω˘)', NULL, NULL),
	(492, 1689608830, '翊', '幸福是五月的阳光
