	(506, 1689763409, '青い鳥の涙', '为了你我愿意不管重复轮回多少次，也会将你救回，如果世界上有将爱能转换成能量的东西的话，那一定是会比太阳还炽热且耀眼的', NULL, NULL),
	(507, 1689772753, '橘子树下百合花', '比希望更炽热的情感，比绝望更深邃的事物。
