	(554, 1690179375, 'noRie3-magica', '磕的是圆焰cb向 圆焰的甜不是恋爱番的那种甜 拯救小圆是小焰的道标 但最后救赎了小焰的确实小圆 这种相互救赎真的太完美了！不能说是爱情 我觉得焰对圆是一种依恋以及超越友情爱情的爱 圆她真的好温柔真的像神一样让大家都幸福 真的可以是说爱着所有人
红蓝也是意难平啊
bgm银之庭院好评 特别特别喜欢这首 有种八音盒的感觉 真的和剧场版圆焰在花丛里的那一幕（还有椅子上）真的好温馨感觉 是焰心中最美的一幕了
圆焰 红蓝已经不再只是cp的名字 更是魔圆中少女与少女互相救赎的故事 是这种无法用名词说明的圣洁情感的象征
最后 圆焰永存！魔圆永存！', NULL, NULL),
