	(655, 1693329119, 'studentπi', '好久都没留言了憋的好慌，再次看到大家一起留言就像回家了一样qwq

最近精神状态算是越来越魔怔了，虽然已经取得了外人看来不错的成绩，可在一处关键的不该失败的对手那里失败，仍然像阴云一样笼罩着我。所以我放弃了所有共情，每见着一个对手就像见着仇人一样，神经紧绷着。但我除了自己还能怪谁呢，除了我自己那愚蠢的傲慢外，其他人都没有犯错。这样的心情没人能倾诉，他们要么为我的对手欢呼，要么批评我斤斤计较。真想在下次比赛的时候把他们都暴打一顿。

想打打游戏也不是很顺利，几乎算是跪了一个下午，以前听说过那个难度不好打，没想到能这么不好打，明明不是类魂游戏但花式暴毙上瘾，也不是很遭了吧。

圆焰晚安~', NULL, NULL),
