	(661, 1693376558, '下次见面我们可就是', '个人感觉：自始至终都是这样的焰，打一开始就展现出来的非凡的抗压能力和毅力，让她注定在无限轮回中成为一个强大的角色。她和圆其实有一些相像的地方，比如虽然会展现出脆弱的一面，但实际上是很可靠的人，为了想要做的事情会认真考虑。算是敏感的人了，有时被戳到痛处，但是破防什么的崩溃什么的马上就修复好了，抹完泪也能继续猎杀QB。她对未来是很少抱幻想的，也不会有侥幸心理，对任何事情都是考虑考虑下定决心了就会去做，做事周密，可以完成的非常出色，之后面对什么即便不在计划之中也没所谓，因为已经习惯变故了。
大多数时候表情比较冷淡，或者说有点没所谓的样子，不过即便不常展现出什么表情，似乎仍然是个很好懂的孩子。
圆在的时候情绪会比较激动，有点强硬；圆不在的时候就会变回平静甚至冷淡的模样，其实可能是因为对什么都不太在乎，比较随便。是个看不出在想些什么的孩子。
爱惜自己的武器，在看不见的角落也许会清理修缮之类？', NULL, NULL),
