	(692, 1693688212, '2011_Luluzi', '一个不明意义的文（？ 
我以过的每一天都很窒息了，对于我来说，我讨厌付出教育，讨厌造谣我是偷钱的陌生人，讨厌80我的同学，后来看到一张圆焰的同人图直接爱上了，后来知道是什么动漫后火速看完了，我很喜欢魔圆其中最喜欢的就是小焰和小圆，小焰和小圆就好像是我黑暗地人生中的一条光，我开始买周边，买不到就自已做每次回到家第一时候间就是去看看喜欢的太太写的文更新了没，魔圆陪着我度过最黑暗的时（小学），我现在也以已快14岁了（现在13），也初一了，看魔圆也有两年左右了。我也有句话想说，谢谢魔圆陪着我度过人生中最黑暗的几年，最后让我说一句，小焰小圆保佑', '638292850124041657', NULL),
