	(780, 1695921271, 'kolde', '圆神，今天是第五天了，下午把屋子清理出来，又把家具重新摆了摆，现在感觉好多了，晚上出去吃了个肯德基，之后又去买了点收纳用品，约莫11点左右，回国的舍友到家了，俩人能聊了一个多小时，明天就开始往外搬东西了，另一个舍友大半夜还没回来，也不知道干啥去了，总之就这样吧，明天早起帮人搬东西，晚安！', NULL, NULL),
