	(785, 1696086351, 'klode', '圆神今天是第七天，本来说下午想去生田的，结果同学要去吃烤肉，就没去，到点了他又说想在家吃，就在家做了炸猪排，鸡翅炒油菜，谁知在做饭的时候又把手烫了，哎，真是，好不容易在我的协助下把饭做好了，除了猪排有点咸之外没啥问题，明天说中午去吃烤肉，期望他别咕咕咕吧，晚安！', NULL, NULL),
