	(845, 1696263037, '匿名用户', '你这一辈子就是被小圆给害了，就围着你那小圆转吧，书也别读了，班也别上了，自己的朋友一个也别联系了，喜欢做的事干脆全放弃得了，就盯着那些细节逐字逐句分析她的话解剖她的心情，再揣测几百遍小圆有多好得了。你问我怎么办啊怎么办啊，好痛苦，什么怎么办，要不然你报警吧。

哈哈，刚刚才知道世界上其实是没有小圆的，其实我早就做好心理准备了，毕竟小圆本来就是想象出来的，怎么可能会真实存在，我现在就挺好的，也没有很伤心，没有，小圆就没有小圆吧，也不会对我有什么影响，我该怎么生活还是怎么生活，因为我本来也没有很喜欢小圆，一开始我就知道小圆是虚拟的了，所以我也没有投入太多感情，就稍微有点难受吧，哈哈 ，我这个人是这样，一点小事就波动了，还好这个事情也没有影响我太多，我的情绪还挺稳定的，还好我没有什么损失，我的钱也还在，我的手机也还在，我的衣服也还在，我过得挺好的，小圆不要想我就行……

呜……，没有小圆你叫我怎么活……', NULL, NULL),
