	(1233, 1696787750, 'klode', '圆神，今天是第14天，上午舍友没有起来呢，我带着大哥大姐去了二条城，中午在那吃了个日式茶点，味道还不错，就是甜点太甜了，之后跟天气预报一样下起了雨，下午带着他俩去了梅小路公园，结果那边开了音乐博览会，公园封了，旁边的水族馆也满员状态，排长队咯，本来想去看看音乐会的，结果打伞不让进，只好先去看了看铁道博物馆，出来的时候正好发现一个全家，就进去买了三份雨衣，顺便吃了点三明治什么的，进了音乐会没几分钟人家就结束了，倒霉倒霉倒霉，之后坐jr回了家，顺路买了点东西，又花了不少钱，晚上吃的饭还是蛮好的，明天依旧是下雨，晚安！', NULL, NULL),
