	(1237, 1696863255, '匿名用户', '圆神晚上好～', NULL, NULL),
	(1238, 1696865347, 'Lutein', '圓神晚安(´◡`)', NULL, NULL),
	(1239, 1696865988, 'klode', '圆神，今天是第15天，本以为有雨的，结果今天硬是没下雨，被天气预报忽悠了，下午带着大哥大姐去了三条，不过大哥对三条的购物街明显没啥兴趣，我就把大姐甩给舍友了，自己带大哥去逛了逛平安神宫，之后去鸭川边吃了点东西，顺着河走回了三条，在星巴克汇合了，之后吃了点牛排就去京都站赴宴，日料还是吃不惯呢，提前离席跟舍友去旁边喝了点咖啡，大概九点左右往回走了，又导车买了点东西，回家已经十点多了，累死人了，晚安！', NULL, NULL),
	(1240, 1696867404, '圆神万岁', '小圆，两天不见。
