	(1330, 1697991484, 'klode', '圆神，今天是第27天，一大早就去看赛马了，只能说日本对赛马的激情还真是高，不过今天居然有骑手摔了，真吓人，下午回家歇了会，帮同学把家搬了，这下算是彻底搬走了，祝他过得好吧，晚上去鞍马看火祭，第一次看见睿电这么多人，一大半都是老外呢，趁祭还没开始去森林里逛了逛，看到了很多废弃的屋子跟车辆残骸什么的等等，怎么有股末世的味道，天黑之后就开始了，整个村落都在门口点了火把，还有游行活动，不过山里太冷了衣服穿少了，八点多就回来了，晚上吃了个炒面，明天又要早起上课了，晚安！', NULL, NULL),
