仿佛像是前面有道光，一直在追着光跑，但是不知道之后是什么，可能只是挂在悬崖上的一轮太阳。
希望一切顺利，希望不要辜负自己三年之期的执念，恳求您保佑我，谢谢圆神，晚安。', NULL, NULL),
