	(1416, 1698860188, 'danshenmiao', '小焰晚安。昨天没来呢，今天了解了量子隐形传态，里面涉及到的伦理问题：传输过去后重构的自己还是自己吗？让我想到了之前看的一部动漫，叫《重启咲良田》。里面本来不该在那个时间点死去的女二相麻菫却在重启后死去了，之后男主通过不同人的能力让她从相片中复活。相麻菫为了让自己相信自己不是自己而自杀，从目的上来说相麻菫复活后就已经不是原来的那个她了。但从照片中出来的相麻菫从形态记忆上都和两年前那个物质上死去的相麻菫相同，并且她死前通过他人的能力传话给两年后的自己，最后也确实收到了传话。所以复活后的相麻菫到底是不是相麻菫呢？这是个很难回答的问题，网上也有不同的说法。
而量子隐形传态并不是将整个人传输到目的地，而是将整个人解构，然后将所有粒子的状态传输到目的地，最后在目的地重构。那么这也会导致和相麻菫相似的问题，重构后的你到底还是不是你呢？重构后的你拥有和先前一样的记忆、人格和身体状况，但已是有全新的物质构成。通俗来讲就是把原来的你给给轰成渣，然后在其他地方用同种但不是原来的物质把你复活，而你本人没有任何感觉，他人看来也不过是瞬移罢了。到底是不是原来的你这不好说，每个人价值观不同看法也不同，终究是取决于传输者本人的看法。
这和又让我想起之前看叛逆时的一个疑问，被小焰从圆环之理中剥离出来的小圆还是原来的小圆吗，相比成神后的小圆应该是截然不同的，那相比成神前的呢？
发了这么久的癫也该睡了，慢慢想吧，有些问题或许永远没有答案吧。', NULL, NULL),
	(1417, 1698861560, '长久相伴', '小圆小焰好，本来想说晚上好的，但是想想现在已经是深夜了呢。不过还是想向你们问好，你们最好啦。
今天依旧没完成计划，晚上跟家里打电话的时候又因为暂时无法解决的老问题，使得心情有点惆怅。不想去怪谁，好想知道我以后能不能有能力解决呢？
小圆小焰你们是两个特别可爱的小女孩，三次元的一切都复杂多变、时常委曲求全，可是我坚信你们会永远在一起的，爱会祝福守护你们，这是我莫大的安慰。
本来打算听了八音盒版的银之庭院就睡觉，但却无法入睡。想想明天你们的身边仍然有着彼此的陪伴，我也想早点见到你们呢。', NULL, NULL),
