	(1490, 1699799279, '圆酱', '圆神……需要圆神的拯救。。。明明跟群友说好不会自残了，又在手上割了几下，伤心的事太多了，真的承受不住，好累……', NULL, NULL),
	(1491, 1699802969, 'danshenmiao', 'j', NULL, 1),
	(1492, 1699803804, '圆环外的往事', '圆神晚安~', NULL, NULL),
	(1493, 1699804326, 'klode', '圆神，今天是第45天，睡了一上午，本来说下午去奈良拍照，结果人家取消了，于是又我在下午睡了一阵，晚上同学拉人来家煮火锅，我就去大原玩了玩，不得不说山里真的冷，差点冻死，不过景色到时不错，虽然手机拍夜景贼拉，没法子，明天还要上课，晚安！', NULL, NULL),
	(1494, 1699804386, 'danshenmiao', '圆焰晚安。今天把魔纪第一季看了，沙耶香出场时真的把我笑到了，但是后面几集真的好悲伤，把我的情绪带动了起来。还把巨人看完了，最后的悲剧真是令人惋惜。人生在世也会遇到许多悲伤的事，或许不如小圆你们那般绝望，不如巨人那般悲壮，但依旧是常人难以忍受的，我们只能无视自己的疲惫，强撑着承受过去，并期盼着明天能够迎来希望。日后再想起那段悲伤的往事，只能苦笑着带过，但或许苦笑的时候我们已经迎来了希望，才能有勇气去回忆那悲伤之事。', NULL, NULL),
