	(1523, 1700140043, '浩劫者12345', '给近几天留言发不出去的人道个歉😭😭😭

十几天前我去掉了madohomu.love强制跳转备用域名, 但因为服务器没有设置好CORS preflight跨域, 导致访问madohomu.love主域名的时候, 发留言的请求 (会发到备用域名所在的服务器) 被浏览器拦截, 最终会卡在"正在发送", 

而访问备用域名的人没有这个问题, 因为不涉及跨域, 所以部分人还是可以发出留言, 让我没有意识到出了问题

查了日志, 总共29条留言因为这个原因发不出来
在此再次道歉！！本当にすみません！

下次一定把基本功能全测试一遍再部署QAQ


* 碎碎念

这个CORS preflight涉及我的知识盲区了。之前一直以为设置了 access-control-allow-origin: * 就是允许跨域了, 没想到只对GET生效, 在POST的时候还得有个preflight。我看到可以正常加载评论就以为可以正常发评论了, 所以一直没测试

直到今天群友问我为什么发不出评论, 我自己试了一下才发现... CORS报错了

下面是给服务器增加的配置项, 加了allowHeaders和allowMethods才能使CORS真正生效', '638357368439588361', NULL),
