	(1626, 1701010257, 'klode', '圆神，今天是第58天，下午徒步从家去了贵船，能走了又两个小时，累死了，到贵船口后坐着大巴上了山，今天是夜间赏枫叶的最后一天，人依旧很多呢，景色也很好看，里面还有个小手工市场，里面有个卖镂空葫芦灯的摊位，我买了个当纪念，之后去贵船神社祈祷了祈祷，还有个很好玩的水占卜，居然是小吉，，运气还不错，接着去求了个御朱印买了本手账，之后走去鞍马做电车回去了，还坐过站了，ε=(´ο｀*)))唉，晚上吃的铁板炒面，味道还是一如既往的好，明天还要上课呢，晚安！', NULL, NULL),
