	(1633, 1701023893, 'studentπi', '自上次连发三四个留言没发出去后有段时间没来了www
现在觉得曾经的自己对圆神有些误解，本以为圆神期望我要坚守对美好未来抱有希望的信念，却忘记了小圆妈妈“努力本身就是意义”，以至于当结果不能如愿回应我的期待时，我的信念开始动摇，真的很不坚强呢。
