	(1673, 1701363484, 'klode', '圆神，今天是第62天，下午上课之前去了趟卢鹭森神社，离家挺近的呢，不过之前一直也没来过，参道上的枫叶令人印象深刻，之后去了附近的赤山禅院，是个佛寺，在山上，当然御朱印也没忘了，之后三点来钟把房费交了，还买了瓶洗发水，赶着上课之前到了教室，差一点呢，晚上吃的肯德基，本来说去贵船神社的，结果舍友又犯懒癌了，哎，今天就这样了，晚安！', '638369604727818741', NULL),
