	(1689, 1701536876, 'klode', '圆神，今天是第64天，中午起床吃的梦雨，之后准备去鞍马收集朱印，结果由岐神社三点就下班了，呃呃，只拿到了鞍马寺的，之后趁着天还没黑去了北野天满宫，在那边看了最后的夜枫，还吃了点茶点，回家之后舍友又找不着钱包，又拉我去警局报案，他明天又要去考n2，没有在留卡很麻烦，回去的途中碰到一个刚来日一个月多的交换生，聊得很投机呢，在外面逛了两个多小时，给他介绍这片地区的情况，好不容易送人家回去，舍友又忘打印准考证了。。。真是累人的一天，晚安！', '638371336768597349', NULL),
