	(1699, 1701617411, 'klode', '圆神，今天是第65天，舍友一大早就去考试了，下午去的圆通寺，不大的日式庭院，里面景色挺美的，之后去了妙满寺，里面这个寺庙挺大的，有一个挺宏伟的主殿，旁边还有一个高耸的石塔，在这终于集齐了10个朱印拿到了第一部分的奖励，呼，那之后走回了家，舍友回来后莫名其妙在包里找到钱包了，也算个good end，明天还要上学，晚安~', NULL, NULL),
