	(1718, 1701790306, 'klode', '圆神，今天是的第67天，中午下了课又去吃冬锅了呢，之后直接去了大原，今天到了寂光院跟宝泉院，寂光院不算很大，在参拜的过程中遇到了看上去很虔诚的三个人，池子里面的鱼还挺有精神的，在拿朱印的时候工作人员因为我的本子跟桌面颜色太像了导致完全忘记了这件事，难蚌，至于宝泉院之前已经去过一次了，不过是在夜间去的，这次尝了他们家的抹茶，在里面坐了一个钟头，虽然枫叶还没落完，但是已经一片萧瑟的景象了，不过庭院的内景还是不错，大概五点半到家准备上课，明天终于不用早早起床了，晚安！', '638373871068032222,638373871068048698', NULL),
