圆焰晚安~', NULL, NULL),
	(1751, 1702141469, 'danshenmiao', '圆焰晚安。一直都想着写个小游戏，现在总算可以开始了。今天哪都没去，但过的还挺充实的。还看了几集寒蝉鸣泣之时，刚开始看的时候其实是挺多疑问的，但在看了后面的篇章后很多问题都被解决了，但又多了很多问题，像这种设定和叙事方式只看一遍可能理解不了全部。目前看来没杀过人的好像只有梨花和纱都子，看到祟杀篇时一直很疑惑纱都子为什么一直要这样对自己，要继续承受虐待，为什么圭一有勇气去杀人，为什么纱都子的叔父还活着，为什么大石看起来和前面性格有点不一样。好多疑惑。不过后面目明篇也算知道纱都子那样做的原因，毕竟被那样指责被那样残忍的杀掉，现在最心疼的就是纱都子了。希望后面能一切明目，能有个好结局。', NULL, NULL),
	(1752, 1702142465, 'klode', '圆神，今天是第71天，中午一如既往地去吃了梦雨，下午去神户的生田神社给人买了个御守溜达了溜达就回来了，明天约了人去逛该，今天早点睡了，晚安！', '638377392656465103', NULL),
