	(1759, 1702213887, 'klode', '圆神，今天是第72天，上午准时出现了呢，二人就一起去了二年坂，之后顺路走到了清水寺，就进去看了看，在里面敲缸拜了拜，莫名其妙就走到清水山了，被忽悠着爬到了山顶，之后又原路出了清水寺，本来想找之前我一前吃过的餐厅来着，结果一路走到八坂神社也没看到之前那个餐厅，白走了一路，最后还是坐车去了百万遍这边吃了个吉野家，饭后去下鸭神社散步了散步，最后做睿电回家了，呼，今天走的真累，先歇了，晚安！', '638378106874252359', NULL),
