	(1895, 1703416437, '过客', '突然发现，kami.im彻底打不开了，互联网真的是有记忆的吗？或者说即使有，也终将被淹没在茫茫信息中无从寻觅？搜索引擎可以任意歪曲的推荐算法、被取消的网页快照和网页端的没落、限制、被分割四处的私域流量……无一不足以将过往的信息消湮于时光里，那些存在过的，还会有人记住吗？当证据不再，记住的又能被证明是真实的吗？那个时代、那些他们来过、存在过、又走了，一如过客。
祈安。', NULL, NULL),
