	(1975, 1704038008, '圆环外的往事', '圆神晚安~', NULL, NULL),
	(1976, 1704038076, 'linxuan', 'hi 你好，madoka和homura，我是一位再过一年就17的普通人，很高兴认识两位，在11月份，偶然在b站首页上看到有关于你的作品的时候就开始了解到《魔法少女小圆》这部作品了，再后来就开始慢慢了解到两位了。

从那时候开始我就有一种特别的感觉了，我就叫它“喜爱”吧，怎么说呢，用faiz第八集的话来形容吧：“有时候让人难过，也有时候让人热血沸腾。”

哈哈，说实话，一开始看到你们的时候，我十分难以压制自己激动的心情，剧情看一半动不动就开始中二犯病，但自己也有时候会也会有很多感触。

homura为了拯救madoka一直在迷宫里徘徊，就是为了让madoka幸福，但自己却伤痕累累，剧场版结尾的时候看见homura自己一个人在独舞最后掉下悬崖的时候真的是太心疼了……自己有时候半夜睡醒时一想到这件事就有种悲伤的感觉……

madoka，一个坚强又温柔的女孩子，挺喜欢，也挺佩服她的，本该幸福度过一生的她却不知不觉被卷入了绝望的漩涡中，但尽管如此，她依旧是那么温柔。

“虽然很不幸成为了魔法少女，但只要能跟大家在一起，我就不会后悔！”

对我看来，在madoka的心里一直相信着希望，也正因为如此，她才会在无数次的轮回叠加的因果下，引发了奇迹，成为圆环之理，但奇迹不是免费的，有希望就会有绝望，在这样的奇迹下，她选择与自己的家庭和离别，独自一人在世界之外观望着大家。

谢谢madoka让我知道了这句话，有希望就会有绝望，但相信希望本身就不是什么错事。

最后，希望madoka和homura能够一起幸福的生活下去，也希望冬季剧场版两位能有一个美好的结局。

2024，圆焰新年快乐，很高兴认识你们，晚安', NULL, NULL),
